INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT118-S3-Q1$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Conclusion$batch06$, $batch06$(Susan, implied) The 30 percent increase does not show the campaign worked.$batch06$), (1, $batch06$Evidence$batch06$, $batch06$Most of the increase came in the first six months, right after free clinics opened and before the campaign really got going.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$Yuriko credits the campaign for the 30 percent rise. Susan does not dispute the number. She points to timing: most of the increase came before the campaign got going, when something else (the clinics) arrived. That suggests another cause and weakens Yuriko's evidence.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Citing facts that weaken the evidence behind Yuriko's recommendation.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT118-S3-Q1$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
